class Solution {
public:
    string clearStars(string s) {
        int n = s.size();
        vector<vector<int>> stacks(26);
        vector<bool> removed(n, false);
        for (int i = 0; i < n; ++i) {
            if (s[i] == '*') {
                for (int c = 0; c < 26; ++c) {
                    if (!stacks[c].empty()) {
                        removed[stacks[c].back()] = true;
                        stacks[c].pop_back();
                        break;
                    }
                }
            } else {
                stacks[s[i] - 'a'].push_back(i);
            }
        }
        string res = "";
        for (int i = 0; i < n; ++i) {
            if (!removed[i] && s[i] != '*') {
                res += s[i];
            }
        }
        return res;
    }
};

class Solution {
    public String clearStars(String s) {
        int n = s.length();
        List<Integer>[] stacks = new ArrayList[26];
        for (int i = 0; i < 26; ++i) stacks[i] = new ArrayList<>();
        boolean[] removed = new boolean[n];
        for (int i = 0; i < n; ++i) {
            char ch = s.charAt(i);
            if (ch == '*') {
                for (int c = 0; c < 26; ++c) {
                    if (!stacks[c].isEmpty()) {
                        int idx = stacks[c].remove(stacks[c].size() - 1);
                        removed[idx] = true;
                        break;
                    }
                }
            } else {
                stacks[ch - 'a'].add(i);
            }
        }
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < n; ++i) {
            if (!removed[i] && s.charAt(i) != '*') {
                res.append(s.charAt(i));
            }
        }
        return res.toString();
    }
}

var clearStars = function(s) {
    const n = s.length;
    const stacks = Array.from({ length: 26 }, () => []);
    const removed = new Uint8Array(n);
    for (let i = 0; i < n; ++i) {
        if (s[i] === '*') {
            for (let c = 0; c < 26; ++c) {
                if (stacks[c].length > 0) {
                    removed[stacks[c].pop()] = 1;
                    break;
                }
            }
        } else {
            stacks[s.charCodeAt(i) - 97].push(i);
        }
    }
    const res = [];
    for (let i = 0; i < n; ++i) {
        if (!removed[i] && s[i] !== '*') {
            res.push(s[i]);
        }
    }
    return res.join('');
};
